import {sceneStatus,appliedSceneStatus} from './engine.mjs';
import {validateSceneDraft} from './scene-model.mjs';
import {MAX_VARIANTS,validateVariant,validateFavorites} from './variants-model.mjs';
export function mountVariants(api){
 const {node,button,t,getState:get,persist,computed,copy,download}=api,widgets=new Map(),KEY='artoftomworks.scene-dna.saved-scenes.v1';
 let favorites={schema:'artoftomworks.scene-dna.scene-favorites',version:1,entries:[]};try{favorites=validateFavorites(JSON.parse(localStorage.getItem(KEY)));}catch{}
 const uid=()=>crypto.randomUUID(),clone=d=>({...structuredClone(d),applied:false});
 const caption=v=>v.name||t({natural:'variantNatural',filmic:'variantFilmic',creative:'variantCreative',custom:'variantCustom',previous:'variantPrevious'}[v.type]);
 const same=(a,b)=>a.text===b.text&&a.base===b.base&&a.imageKey===b.imageKey&&JSON.stringify(a.settings)===JSON.stringify(b.settings);
 function extraSlot(shot){const d=shot.sceneDraft;if(!d?.text.trim())return 0;return shot.sceneVariants?.some(v=>v.id===shot.sceneActiveVariant||same(v.draft,d))?0:1;}
 function room(shot,n){if((shot.sceneVariants?.length||0)+extraSlot(shot)+n<=MAX_VARIANTS)return true;api.inform(shot.id,t('variantLimit'));return false;}
 function archive(shot){shot.sceneVariants??=[];const d=shot.sceneDraft;if(!d?.text.trim())return;let v=shot.sceneVariants.find(v=>v.id===shot.sceneActiveVariant)||shot.sceneVariants.find(v=>same(v.draft,d));if(v){v.draft=clone(d);shot.sceneActiveVariant=v.id;return;}v=validateVariant({id:uid(),type:'previous',name:'',draft:clone(d)});shot.sceneVariants.push(v);shot.sceneActiveVariant=v.id;}
 function syncCurrent(shot){const v=shot.sceneVariants?.find(v=>v.id===shot.sceneActiveVariant);if(v&&shot.sceneDraft)v.draft=clone(shot.sceneDraft);}
 function choose(shot,variant,focus=false){if(api.busy()||!room(shot,0))return false;archive(shot);shot.sceneDraft=clone(variant.draft);shot.sceneActiveVariant=variant.id;persist();computed();api.refresh();if(focus){const area=api.editor(shot.id);area?.scrollIntoView({behavior:'smooth',block:'center'});area?.focus({preventScroll:true});}return true;}
 function apply(shot,v){if(api.busy()||!v.draft.text.trim())return;const check=sceneStatus(get(),{...shot,sceneDraft:v.draft});if(check.stale&&!confirm(t('sceneReview')))return;if(choose(shot,v))api.apply(shot,true);}
 function makeDraft(payload,origin,snap,model){return validateSceneDraft({version:1,applied:false,origin,source:snap.settings.source,imageKey:snap.imageKey,text:payload.videoPrompt,summary:payload.summary||'',observations:payload.observations||'',base:snap.base,model:model||'',settings:snap.settings});}
 function appendBatch(shot,payloads,origin,snap,model){if(!room(shot,payloads.length))return false;let variants;try{variants=payloads.map(p=>validateVariant({id:uid(),type:p.type,name:'',draft:makeDraft(p,origin,snap,model)}));}catch{api.inform(shot.id,t('sceneError'));return false;}archive(shot);shot.sceneVariants.push(...variants);if(!shot.sceneDraft?.text.trim()){shot.sceneDraft=clone(variants[0].draft);shot.sceneActiveVariant=variants[0].id;}persist();computed();api.inform(shot.id,t('variantsReceived'));refresh();return true;}
 function addOwn(shot){if(api.busy()||!room(shot,1))return;archive(shot);const snap=api.snapshot(shot),v=validateVariant({id:uid(),type:'custom',name:'',draft:makeDraft({videoPrompt:'',summary:'',observations:''},'manual',snap,'')});shot.sceneVariants.push(v);choose(shot,v,true);}
 function storeFavorites(next,id){try{const checked=validateFavorites(next);localStorage.setItem(KEY,JSON.stringify(checked));favorites=checked;api.inform(id,t('favoriteSaved'));refresh();return true;}catch{api.inform(id,t('favoriteError'));return false;}}
 function save(shot,variant){if(api.busy()||!variant.draft.text.trim())return;const name=window.prompt(t('variantName'),caption(variant));if(name===null||!name.trim())return;try{const saved=validateVariant({...variant,id:uid(),name:name.trim(),draft:clone(variant.draft)}),entries=favorites.entries.filter(v=>!(v.name===saved.name&&v.draft.text===saved.draft.text));storeFavorites({...favorites,entries:[...entries,saved]},shot.id);}catch{api.inform(shot.id,t('favoriteError'));}}
 function saveCurrent(shot){if(shot.sceneDraft?.text.trim())save(shot,{id:uid(),type:'custom',name:'',draft:shot.sceneDraft});}
 function card(parent,shot,v){const article=node('article');article.className='scene-variant';article.dataset.variantId=v.id;const title=node('h4'),state=node('p'),summary=node('p'),preview=node('p');state.className='variant-status';preview.className='variant-preview';const actions=node('div');actions.className='toolbar variant-actions';const edit=button(t('variantEdit'),()=>choose(shot,v,true)),copyButton=button(t('copy')+' · '+t('videoPrompt'),()=>{if(!sceneStatus(get(),{...shot,sceneDraft:v.draft}).stale)void copy(v.draft.text);}),applyButton=button(t('sceneApply'),()=>apply(shot,v),'primary'),saveButton=button(t('variantSave'),()=>save(shot,v)),remove=button(t('variantRemove'),()=>{if(api.busy()||!confirm(t('variantRemove')+' · '+caption(v)+'?'))return;shot.sceneVariants=shot.sceneVariants.filter(x=>x.id!==v.id);if(shot.sceneActiveVariant===v.id)delete shot.sceneActiveVariant;if(shot.sceneAppliedVariant===v.id)delete shot.sceneAppliedVariant;persist();computed();refresh();});edit.dataset.variantEdit='';copyButton.dataset.variantCopy='';applyButton.dataset.variantApply='';saveButton.dataset.variantSave='';remove.dataset.variantRemove='';actions.append(edit,copyButton,applyButton,saveButton);const more=node('details');more.append(node('summary',t('variantRemove')),remove);article.append(title,state,summary,preview,actions,more);parent.append(article);return {article,title,state,summary,preview,edit,copy:copyButton,apply:applyButton,save:saveButton,remove};}
 function favoriteControls(parent,shot){const details=node('details');details.className='scene-favorites';details.append(node('summary',t('favoritesTitle')),node('p',t('favoriteReview')));const label=node('label');label.append(node('span',t('favoritesTitle')));const select=node('select');select.dataset.favoriteSelect='';label.append(select);const actions=node('div');actions.className='toolbar';const add=button(t('favoriteAdd'),()=>{const found=favorites.entries.find(v=>v.id===select.value);if(api.busy()||!found||!room(shot,1))return;archive(shot);const v=validateVariant({...found,id:uid(),draft:clone(found.draft)});shot.sceneVariants.push(v);persist();computed();refresh();}),remove=button(t('favoriteRemove'),()=>{if(!select.value||!confirm(t('favoriteRemove')+'?'))return;storeFavorites({...favorites,entries:favorites.entries.filter(v=>v.id!==select.value)},shot.id);}),exportButton=button(t('favoriteExport'),()=>download(JSON.stringify(favorites,null,2),'SceneDNA_SavedScenes.json','application/json')),picker=node('input');picker.type='file';picker.accept='.json,application/json';picker.hidden=true;picker.dataset.favoritePicker='';const importButton=button(t('favoriteImport'),()=>{picker.value='';picker.click();});picker.onchange=async()=>{const file=picker.files[0];if(!file)return;try{if(file.size>3*1024**2)throw Error();const incoming=validateFavorites(JSON.parse(await file.text())),merged=new Map(favorites.entries.map(v=>[v.id,v]));for(const v of incoming.entries)merged.set(v.id,v);storeFavorites({...favorites,entries:[...merged.values()]},shot.id);}catch{api.inform(shot.id,t('favoriteError'));}};add.dataset.favoriteAdd='';remove.dataset.favoriteRemove='';exportButton.dataset.favoriteExport='';importButton.dataset.favoriteImport='';select.onchange=()=>{add.disabled=remove.disabled=!select.value||api.busy();};actions.append(add,remove,exportButton,importButton);details.append(label,actions,picker);parent.append(details);return {select,add,remove,exportButton,picker,importButton};}
 function render(parent,shot){const section=node('section');section.className='scene-variants';const header=node('div');header.className='section-head';const heading=node('h3',t('variantsTitle')),count=node('span');count.className='muted';header.append(heading,count);let seen=false;try{seen=localStorage.getItem('artoftomworks.scene-dna.new.variants')==='seen';}catch{}if(!seen){const badge=button('NEW ×',()=>{try{localStorage.setItem('artoftomworks.scene-dna.new.variants','seen');}catch{}for(const n of document.querySelectorAll('.variants-new'))n.remove();},'badge variants-new');badge.setAttribute('aria-label',t('cropDismiss'));header.append(badge);}const help=node('p',t('variantsHelp')),list=node('div');list.className='variant-grid';const empty=node('p',t('variantsEmpty')),own=button(t('variantsNew'),()=>addOwn(shot));own.dataset.variantNew='';section.append(header,help,list,empty,own);const favoritesUI=favoriteControls(section,shot);parent.append(section);widgets.set(shot.id,{list,count,empty,own,cards:new Map(),favorites:favoritesUI});refresh();}
 function refresh(){const favoriteSignature=favorites.entries.map(v=>v.id+v.name).join('|');for(const shot of get().shots){const w=widgets.get(shot.id);if(!w)continue;const all=shot.sceneVariants||[],busy=api.busy();w.count.textContent=all.length+' / '+MAX_VARIANTS;w.empty.hidden=all.length>0;w.own.disabled=busy||all.length+extraSlot(shot)>=MAX_VARIANTS;const ids=all.map(v=>v.id).join('|');if(w.ids!==ids){w.list.replaceChildren();w.cards.clear();for(const v of all)w.cards.set(v.id,card(w.list,shot,v));w.ids=ids;}const active=appliedSceneStatus(get(),shot);for(const v of all){const c=w.cards.get(v.id),stale=sceneStatus(get(),{...shot,sceneDraft:v.draft}).stale,applied=active.active&&shot.sceneAppliedVariant===v.id&&shot.sceneApplied?.text===v.draft.text;c.title.textContent=caption(v);c.state.textContent=[shot.sceneActiveVariant===v.id?t('variantSelected'):'',applied?t('sceneApplied'):stale?t('sceneStale'):t('variantPending')].filter(Boolean).join(' · ');c.summary.textContent=v.draft.summary.slice(0,180);c.preview.textContent=v.draft.text.length>220?v.draft.text.slice(0,220)+'…':v.draft.text;c.edit.disabled=c.remove.disabled=busy;c.apply.disabled=c.save.disabled=busy||!v.draft.text.trim();c.copy.disabled=busy||stale||!v.draft.text.trim();c.article.classList.toggle('is-applied',applied);c.article.classList.toggle('is-selected',shot.sceneActiveVariant===v.id);}
 const f=w.favorites;if(f.signature!==favoriteSignature){const old=f.select.value;f.select.replaceChildren(new Option(favorites.entries.length?t('choose'):t('favoriteEmpty'),''));for(const v of favorites.entries)f.select.append(new Option(v.name,v.id));if(favorites.entries.some(v=>v.id===old))f.select.value=old;f.signature=favoriteSignature;}f.add.disabled=f.remove.disabled=busy||!f.select.value;f.exportButton.disabled=!favorites.entries.length;f.importButton.disabled=busy;}}
 return {render,refresh,room,appendBatch,syncCurrent,saveCurrent,clearWidgets:()=>widgets.clear()};
}
